setup:
set lock_timeout = '3s';
set default_transaction_isolation = 'read committed';
drop table if exists pe_visibility;
create table pe_visibility (id int primary key, balance int not null);
insert into pe_visibility values (1, 100);

code:
-- Session A: write, then inspect your own uncommitted version. Leave A open.
begin;
update pe_visibility set balance = 120 where id = 1;
select balance as a_private from pe_visibility where id = 1;

-- Session B: read from a separate connection while A is still open.
set default_transaction_isolation = 'read committed';
set lock_timeout = '3s';
select balance as b_before_commit from pe_visibility where id = 1;

-- Session A: make the first change committed.
commit;

-- Session B: take a fresh statement view after A's commit.
select balance as b_after_commit from pe_visibility where id = 1;

-- Session A: try a different value, but abandon this transaction.
begin;
update pe_visibility set balance = 999 where id = 1;
select balance as a_aborted from pe_visibility where id = 1;
rollback;

-- Session B: check which value survived, then remove this lesson's table.
select balance as b_after_rollback from pe_visibility where id = 1;
drop table pe_visibility;

setup:
set lock_timeout = '3s';
set default_transaction_isolation = 'read committed';
drop table if exists pe_snapshot;
create table pe_snapshot (id int primary key, balance int not null);
insert into pe_snapshot values (1, 100);

code:
-- Session A: first round, Read Committed. Leave the reader transaction open.
begin isolation level read committed;
select balance as rc_before from pe_snapshot where id = 1;

-- Session B: commit a change between A's reads.
set default_transaction_isolation = 'read committed';
set lock_timeout = '3s';
update pe_snapshot set balance = 120 where id = 1;

-- Session A: read again inside the SAME transaction, then end it.
select balance as rc_after from pe_snapshot where id = 1;
commit;

-- Session B: restore the starting value before the second round.
update pe_snapshot set balance = 100 where id = 1;

-- Session A: second round, Repeatable Read. The SELECT establishes its snapshot.
begin isolation level repeatable read;
select balance as rr_before from pe_snapshot where id = 1;

-- Session B: make the same committed change.
update pe_snapshot set balance = 120 where id = 1;

-- Session A: read in the stable view, then finish and take a fresh view.
select balance as rr_after from pe_snapshot where id = 1;
commit;
select balance as fresh_after_end from pe_snapshot where id = 1;
drop table pe_snapshot;

setup:
set lock_timeout = '3s';
set default_transaction_isolation = 'read committed';
create extension if not exists pgstattuple;
drop table if exists pe_history;
create table pe_history (id int primary key, payload text not null)
  with (autovacuum_enabled = false);
insert into pe_history select g, repeat('x', 100) from generate_series(1, 1000) g;
vacuum pe_history;

code:
-- Session A: establish the reader that still needs the original rows. Leave it open.
set application_name = 'pe-history-reader';
begin isolation level repeatable read;
select count(*) as reader_before from pe_history;

-- Session B: delete in a committed statement, then try to reclaim the old versions.
set default_transaction_isolation = 'read committed';
set lock_timeout = '3s';
delete from pe_history;
select count(*) as fresh_rows from pe_history;
select state, backend_xmin from pg_stat_activity
where application_name = 'pe-history-reader' and datname = current_database();
vacuum (truncate false) pe_history;
select dead_tuple_count as retained_dead, free_percent as retained_free
from pgstattuple('pe_history');

-- Session A: prove the retained versions are still readable, then release the snapshot.
select count(*) as reader_after_delete from pe_history;
commit;
reset application_name;

-- Session B: repeat the same vacuum with that reader gone, then clean up.
vacuum (truncate false) pe_history;
select dead_tuple_count as released_dead, free_percent as released_free
from pgstattuple('pe_history');
select count(*) as final_rows from pe_history;
drop table pe_history;

setup:
set lock_timeout = '3s';
create extension if not exists pgstattuple;
drop table if exists pe_reuse;
create table pe_reuse (id int primary key, payload text not null)
  with (autovacuum_enabled = false);
insert into pe_reuse
select g, repeat('x', 400) from generate_series(1, 4000) g;
vacuum pe_reuse;

set lock_timeout = '60s';
set statement_timeout = '90s';
drop table if exists pe_atomic_write;
create table pe_atomic_write (id int primary key, balance int not null);
insert into pe_atomic_write values (1, 100);

code:
-- Session A: read 100 and prepare the supplied replacement 110. Leave A open.
begin isolation level read committed;
select balance as a_read, balance + 10 as a_replacement
from pe_atomic_write where id = 1 \gset
\echo A read :a_read and computed replacement :a_replacement

-- Session B: read the same 100 and prepare the supplied replacement 120. Leave B open.
set lock_timeout = '60s';
set statement_timeout = '90s';
begin isolation level read committed;
select balance as b_read, balance + 20 as b_replacement
from pe_atomic_write where id = 1 \gset
\echo B read :b_read and computed replacement :b_replacement

-- Session A: write the replacement calculated from A's earlier read, then commit.
update pe_atomic_write set balance = :a_replacement where id = 1
returning balance as a_replacement_written;
commit;

-- Session B: write B's stale replacement after A commits, then commit.
update pe_atomic_write set balance = :b_replacement where id = 1
returning balance as b_replacement_written;
commit;

-- Session A: observe the lost increment, then reset for atomic arithmetic.
select balance as after_stale_replacement from pe_atomic_write where id = 1;
update pe_atomic_write set balance = 100 where id = 1;
begin isolation level read committed;
update pe_atomic_write set balance = balance + 10 where id = 1
returning balance as a_atomic_written;

-- Session B (blocks until A commits; switch to A while this waits)
begin isolation level read committed;
update pe_atomic_write set balance = balance + 20 where id = 1
returning balance as b_atomic_written;

-- Session A: release the row after B has started waiting.
commit;

-- Session B: the UPDATE has resumed with A's committed row. Finish B.
commit;
reset lock_timeout;
reset statement_timeout;

-- Session A: inspect the combined arithmetic, restore settings and clean up.
select balance as after_atomic_arithmetic from pe_atomic_write where id = 1;
reset lock_timeout;
reset statement_timeout;
drop table pe_atomic_write;

setup:
set default_transaction_isolation = 'read committed';
set lock_timeout = '60s';
set statement_timeout = '90s';
drop table if exists pe_stock;
create table pe_stock (
  sku text primary key,
  remaining int not null,
  accepted_reservations int not null
);
insert into pe_stock values ('widget', 1, 0);

code:
-- Session A: stale-decision round. Read the last unit and leave this transaction open.
begin;
select remaining as a_stale_read,
       case when remaining > 0 then 'accept' else 'decline' end as a_stale_decision
from pe_stock where sku = 'widget';

-- Session B: read the same last unit before A changes it. Leave B open too.
set default_transaction_isolation = 'read committed';
set lock_timeout = '60s';
set statement_timeout = '90s';
begin;
select remaining as b_stale_read,
       case when remaining > 0 then 'accept' else 'decline' end as b_stale_decision
from pe_stock where sku = 'widget';

-- Session A: follow A's accept decision, then commit.
update pe_stock
set remaining = remaining - 1,
    accepted_reservations = accepted_reservations + 1
where sku = 'widget';
commit;

-- Session B: follow B's earlier accept decision without reading again, then commit.
update pe_stock
set remaining = remaining - 1,
    accepted_reservations = accepted_reservations + 1
where sku = 'widget';
commit;

-- Session A: observe the invalid result, then reset the same row for the locking round.
select remaining as stale_remaining,
       accepted_reservations as stale_accepted
from pe_stock where sku = 'widget';
update pe_stock set remaining = 1, accepted_reservations = 0 where sku = 'widget';

-- Session A: locking round. Lock the row, decide from 1, and leave A open.
begin;
select remaining as a_locked_read,
       case when remaining > 0 then 'accept' else 'decline' end as a_locked_decision
from pe_stock where sku = 'widget' for update;

-- Session B (blocks until A commits): try to lock the row before making B's decision.
begin;
select remaining as b_locked_read,
       case when remaining > 0 then 'accept' else 'decline' end as b_locked_decision
from pe_stock where sku = 'widget' for update;

-- Session A: follow A's accept decision and commit, which releases the row lock.
update pe_stock
set remaining = remaining - 1,
    accepted_reservations = accepted_reservations + 1
where sku = 'widget';
commit;

-- Session B: the blocked SELECT has now returned 0 and decline. Record no write, then finish.
select 'no write: stock is exhausted' as b_locked_action;
commit;
reset lock_timeout;
reset statement_timeout;

-- Session A: compare the protected result, then remove this lesson's table.
select remaining as locked_remaining,
       accepted_reservations as locked_accepted
from pe_stock where sku = 'widget';
reset lock_timeout;
reset statement_timeout;
drop table pe_stock;
